import{_ as o,o as e,c as s,ag as r}from"./chunks/framework.CrXGS008.js";const p=JSON.parse('{"title":"Túneis","description":"","frontmatter":{},"headers":[],"relativePath":"pt/car-wash/tunnels.md","filePath":"pt/car-wash/tunnels.md"}'),i={name:"pt/car-wash/tunnels.md"};function t(n,a,l,d,c,u){return e(),s("div",null,[...a[0]||(a[0]=[r('<h1 id="tuneis" tabindex="-1">Túneis <a class="header-anchor" href="#tuneis" aria-label="Permalink to &quot;Túneis&quot;">​</a></h1><p>Um túnel é uma entrada onde o condutor para, uma linha que o veículo segue, e os arcos, escovas e secador ao longo dela. Dois túneis vêm prontos a usar: <strong>Strawberry</strong> e <strong>Little Seoul</strong>.</p><h2 id="como-funciona-uma-lavagem" tabindex="-1">Como funciona uma lavagem <a class="header-anchor" href="#como-funciona-uma-lavagem" aria-label="Permalink to &quot;Como funciona uma lavagem&quot;">​</a></h2><ol><li>O condutor para na entrada, virado para a saída. Um aviso mostra o preço mais baixo.</li><li><strong>E</strong> abre o menu de lavagem com os programas e os respetivos preços (descontos por profissão e percentagem do túnel incluídos).</li><li>O preço é pago e o veículo é guiado ao longo da linha: sabão, escovas, enxaguamento, secador, conforme o programa. Todos à volta veem a mesma lavagem.</li><li>À saída, o veículo está limpo, e encerado se o programa incluir cera.</li></ol><p>A entrada recusa a lavagem quando:</p><ul><li>o túnel já está a ser usado (um veículo de cada vez);</li><li>o veículo está virado no sentido errado;</li><li>outro veículo bloqueia a passagem;</li><li>a classe do veículo está bloqueada, ou o veículo é demasiado largo (<code>BlockedClasses</code>, <code>MaxVehicleWidth</code>);</li><li>o veículo já está limpo e <code>RequireDirt</code> está ativado;</li><li>o jogador não consegue pagar.</li></ul><h2 id="o-editor-de-tuneis" tabindex="-1">O editor de túneis <a class="header-anchor" href="#o-editor-de-tuneis" aria-label="Permalink to &quot;O editor de túneis&quot;">​</a></h2><p>Abra-o com <code>/nay:carwash</code>, ou com <strong>Gerir túneis</strong> na página Car Wash do <code>/nay</code>. Exige o âmbito <code>nay_car_wash.config</code>.</p><p>O gestor lista os túneis: ir até um, editá-lo, abri-lo ou fechá-lo, eliminá-lo. Para adicionar um:</p><ol><li><p><strong>Criar aqui</strong>: coloque-se na entrada, virado para a saída. Ou <strong>Copiar</strong> uma das lavagens do jogo base.</p></li><li><p>Escolha um elemento (entrada, início e fim da linha, arcos, escovas, secador) e mova-o com os botões ou com o teclado:</p><ul><li>setas: frente, trás, esquerda, direita ao longo da passagem;</li><li>Page Up / Page Down: altura;</li><li>Q / E: rodar;</li><li>Tab: elemento seguinte.</li></ul><p>Há três tamanhos de passo disponíveis para ajustes finos.</p></li><li><p><strong>Para a minha posição</strong> e <strong>Para o chão</strong> encaixam o elemento selecionado. <strong>Deslocar-se</strong> (G) liberta o rato para se mover e olhar em volta. Prima G de novo para voltar ao painel.</p></li><li><p><strong>Guardar túnel</strong>. O túnel passa a estar ativo para todos os jogadores de imediato.</p></li></ol><p>O editor preenche a definição <code>Tunnels</code>. Os respetivos campos estão descritos na página <a href="/pt/car-wash/settings#tuneis">Definições</a>.</p>',11)])])}const g=o(i,[["render",t]]);export{p as __pageData,g as default};
